const MASTER_KEY='master';
const LEVELS=['project','system','typeloc','loc','sub','equip','serial'];
const PROP={project:'project',system:'system',typeloc:'typeLocation',loc:'locName',sub:'subName',equip:'equipment',serial:'serial'};
const LABEL={project:'Project',system:'System',typeloc:'Location Type',loc:'Location',sub:'Sub-location',equip:'Equipment',serial:'Serial Number'};
let master=[],entries=[],assignments=[],assignStats=[],editingId=null,imgMain='',imgSticker='',img3='',img4='';
let awSelProjs=[],awSelLocs=[],awSelSubs=[],awSelEquips=[];
const sel={project:'',system:'',loc:'',sub:'',equip:'',serial:''};
const combos={};
const INSP_SEED=['Somchai Jaidee','Somying Rakngan'];

async function loadAll(){const m=await sGet(MASTER_KEY);if(m){try{master=JSON.parse(m);}catch(e){master=[];}}buildCombos();buildInspectorCombo();refreshDerived();renderMaster();renderSaved();updateStats();}

async function sGet(k){try{return localStorage.getItem(k);}catch(e){return null;}}
async function sSet(k,v){try{localStorage.setItem(k,v);}catch(e){console.warn(e);}}

function optionsFor(level){
  const idx=LEVELS.indexOf(level);let rows=master;
  const role=AUTH.user?.role||'';const userProjs=(AUTH.user?.project||'').split(',').map(p=>p.trim()).filter(Boolean);
  if((role==='leader'||role==='inspector'))rows=rows.filter(r=>userProjs.includes(r.project));
  for(let i=0;i<idx;i++){const lv=LEVELS[i];if(!sel[lv])continue;if((level==='equip'||level==='serial')&&lv==='typeloc')continue;rows=rows.filter(r=>String(r[PROP[lv]]||'')===sel[lv]);}
  if(level==='equip'){const asset=($('#inpAsset')?.value||'').trim();if(asset)rows=rows.filter(r=>String(r.asset||'')===asset);}
  if(level==='serial'){const brand=($('#inpBrand')&&$('#inpBrand').value||'').trim();if(brand)rows=rows.filter(r=>String(r.brand||'')===brand);return uniq(rows.map(r=>String(r.serial||'')).filter(Boolean)).sort((a,b)=>a.localeCompare(b,'th'));}
  return uniq(rows.map(r=>String(r[PROP[level]]||''))).sort((a,b)=>a.localeCompare(b,'th'));
}
function buildCombos(){
  LEVELS.forEach(level=>{
    const el=document.querySelector(`.combo[data-level="${level}"]`);
    el.innerHTML=`<div class="combo-ctl"><input class="combo-input" placeholder="Type or select ${LABEL[level]}..." autocomplete="off"><span class="combo-clear">&times;</span><span class="combo-caret">▾</span></div><div class="combo-list"></div>`;
    const input=el.querySelector('.combo-input'),list=el.querySelector('.combo-list'),clear=el.querySelector('.combo-clear');
    combos[level]={el,input,list};let active=-1;
    const isDisabled=()=>el.classList.contains('disabled');
    function render(filter){let opts=optionsFor(level);const f=(filter||'').trim().toLowerCase();if(f)opts=opts.filter(o=>o.toLowerCase().includes(f));active=-1;let html=opts.map(o=>`<div class="combo-opt" data-v="${escAttr(o)}">${esc(o)}</div>`).join('');const exact=optionsFor(level).some(o=>o.toLowerCase()===f);if(f&&!exact)html+=`<div class="combo-new" data-new="${escAttr(filter.trim())}">+ Use "${esc(filter.trim())}" (new)</div>`;if(!html)html=`<div class="combo-empty">No options</div>`;list.innerHTML=html;list.querySelectorAll('.combo-opt').forEach(o=>o.addEventListener('mousedown',e=>{e.preventDefault();choose(level,o.dataset.v);}));const nw=list.querySelector('.combo-new');if(nw)nw.addEventListener('mousedown',e=>{e.preventDefault();choose(level,nw.dataset.new);});}
    function open(){if(isDisabled())return;el.classList.add('open');render(input.value);}
    function close(){el.classList.remove('open');}
    input.addEventListener('focus',open);input.addEventListener('click',open);
    input.addEventListener('input',()=>{el.classList.add('open');render(input.value);});
    input.addEventListener('keydown',e=>{const items=list.querySelectorAll('.combo-opt,.combo-new');if(e.key==='ArrowDown'){e.preventDefault();active=Math.min(active+1,items.length-1);}else if(e.key==='ArrowUp'){e.preventDefault();active=Math.max(active-1,0);}else if(e.key==='Enter'){e.preventDefault();if(active>=0){const it=items[active];choose(level,it.dataset.v||it.dataset.new);}else if(input.value.trim())choose(level,input.value.trim());return;}else if(e.key==='Escape'){close();return;}items.forEach((it,i)=>it.classList.toggle('active',i===active));if(active>=0)items[active].scrollIntoView({block:'nearest'});});
    input.addEventListener('blur',()=>setTimeout(()=>{close();const v=input.value.trim();if(v!==sel[level])choose(level,v);},150));
    clear.addEventListener('mousedown',e=>{e.preventDefault();choose(level,'');});
  });
  setDisabledStates();
}
function choose(level,val){try{setTimeout(checkSerialWarn,0);}catch(e){}val=String(val||'').trim();if(sel[level]===val){combos[level].input.value=val;combos[level].el.classList.toggle('has-val',!!val);combos[level].el.classList.remove('open');return;}sel[level]=val;combos[level].input.value=val;combos[level].el.classList.toggle('has-val',!!val);combos[level].el.classList.remove('open');const idx=LEVELS.indexOf(level);for(let i=idx+1;i<LEVELS.length;i++){const lv=LEVELS[i];sel[lv]='';if(combos[lv]){combos[lv].input.value='';combos[lv].el.classList.remove('has-val');}}setDisabledStates();updateBrandModel();try{paintReadingField();}catch(e){}if(level==='equip'&&val){setTimeout(()=>{const s=optionsFor('serial');if(s.length===1&&!sel.serial)choose('serial',s[0]);},50);}}
function setDisabledStates(){
  const REQUIRED_ANCESTOR={project:null,system:'project',typeloc:'project',loc:'project',sub:'loc',equip:'loc',serial:'equip'};
  LEVELS.forEach((lv)=>{
    const c=combos[lv];if(!c)return;
    const req=REQUIRED_ANCESTOR[lv];
    const parentOk=!req||!!sel[req];
    if(parentOk){c.el.classList.remove('disabled');c.input.disabled=false;c.input.placeholder=`Type or select ${LABEL[lv]}...`;}
    else{c.el.classList.add('disabled');c.input.disabled=true;c.input.placeholder=`Select ${LABEL[req]} first`;}
  });
  if(combos.serial)refreshSerialCombo();

  const assetWrap=$('#inpAsset')?.closest?.('.combo');
  if(assetWrap){const en=!!sel.loc;assetWrap.classList.toggle('disabled',!en);$('#inpAsset').disabled=!en;$('#inpAsset').placeholder=en?'e.g. Firewall, Switch, Transceiver...':'Select a location first';if(!en&&$('#inpAsset').value){$('#inpAsset').value='';syncComboVal('inpAsset');}}
}
function updateBrandModel(){let rows=master;['project','system','loc','sub','equip','serial'].forEach(lv=>{if(sel[lv])rows=rows.filter(r=>String(r[PROP[lv]]||'')===sel[lv]);});const brands=uniq(rows.map(r=>r.brand)),models=uniq(rows.map(r=>r.model)),assets=uniq(rows.map(r=>r.asset));setBM('bmBrand','inpBrand',brands);setBM('bmModel','inpModel',models);if(assets.length===1&&!$('#inpAsset').value)$('#inpAsset').value=assets[0];}
function refreshSerialCombo(){if(!combos.serial)return;const valid=optionsFor('serial');if(sel.serial&&!valid.includes(sel.serial)){sel.serial='';combos.serial.input.value='';combos.serial.el.classList.remove('has-val');}const ph=sel.equip?(valid.length?`Select Serial (${valid.length} records)`:'No Serial in master data'):'Select equipment first';if(combos.serial.input)combos.serial.input.placeholder=ph;}
function setBM(boxId,inpId,vals){const box=$('#'+boxId),inp=$('#'+inpId);if(sel.equip&&vals.length===1){box.classList.remove('empty');box.innerHTML=`<input id="${inpId}" style="display:none">`+esc(vals[0]);$('#'+inpId).value=vals[0];}else if(sel.equip){box.classList.remove('empty');box.innerHTML=`<input id="${inpId}" placeholder="Enter manually" value="${escAttr(vals[0]||'')}">`;}else{box.classList.add('empty');box.innerHTML=`<input id="${inpId}" style="display:none">`+(box.dataset.empty||'—');$('#'+inpId).value='';}}
function refreshDerived(){
  $('#masterPill').textContent=master.length;
  upgradeToCombo('inpAsset',()=>{
    let rows=master;
    const role=AUTH.user?.role||'';const userProjs=(AUTH.user?.project||'').split(',').map(p=>p.trim()).filter(Boolean);
    if((role==='leader'||role==='inspector'))rows=rows.filter(r=>userProjs.includes(r.project));
    if(sel.project)rows=rows.filter(r=>String(r.project||'')===sel.project);
    if(sel.system)rows=rows.filter(r=>String(r.system||'')===sel.system);
    if(sel.loc)rows=rows.filter(r=>String(r.locName||'')===sel.loc);
    if(sel.sub)rows=rows.filter(r=>String(r.subName||'')===sel.sub);
    return uniq(rows.map(m=>m.asset).filter(Boolean)).sort((a,b)=>a.localeCompare(b,'th'));
  });
  const assetInp=$('#inpAsset');
  if(assetInp&&!assetInp.dataset.equipListener){
    assetInp.dataset.equipListener='1';
    assetInp.addEventListener('input',()=>{if(combos.equip){combos.equip.el.classList.remove('open');combos.equip.list.innerHTML='';}});
    assetInp.addEventListener('change',()=>{
      if(!combos.equip||combos.equip.el.classList.contains('disabled'))return;
      const opts=optionsFor('equip');
      if(opts.length===1){setTimeout(()=>choose('equip',opts[0]),50);}
      else{setTimeout(()=>combos.equip.input.focus(),50);}
    });
  }
}

function upgradeToCombo(inputIdOrEl,getOptionsFn){
  const inp=typeof inputIdOrEl==='string'?document.getElementById(inputIdOrEl):inputIdOrEl;
  if(!inp||inp.dataset.comboUpgraded)return;
  inp.dataset.comboUpgraded='1';
  inp.removeAttribute('list');
  inp.classList.add('combo-input');
  inp.setAttribute('autocomplete','off');
  const wrap=document.createElement('div');wrap.className='combo';
  const ctl=document.createElement('div');ctl.className='combo-ctl';
  inp.parentNode.insertBefore(wrap,inp);
  ctl.appendChild(inp);wrap.appendChild(ctl);
  const clearBtn=document.createElement('span');clearBtn.className='combo-clear';clearBtn.innerHTML='&times;';ctl.appendChild(clearBtn);
  const caret=document.createElement('span');caret.className='combo-caret';caret.textContent='▾';ctl.appendChild(caret);
  const list=document.createElement('div');list.className='combo-list';wrap.appendChild(list);
  let active=-1;
  function render(filter){
    let opts=getOptionsFn();
    const f=(filter||'').trim().toLowerCase();
    if(f)opts=opts.filter(o=>String(o).toLowerCase().includes(f));
    active=-1;
    let html=opts.map(o=>`<div class="combo-opt" data-v="${escAttr(o)}">${esc(o)}</div>`).join('');
    if(!html)html=`<div class="combo-empty">No options</div>`;
    list.innerHTML=html;
    list.querySelectorAll('.combo-opt').forEach(o=>o.addEventListener('mousedown',e=>{e.preventDefault();pick(o.dataset.v);}));
  }
  let _picking=false;
  function pick(v){_picking=true;inp.value=v;wrap.classList.toggle('has-val',!!v);wrap.classList.remove('open');inp.dispatchEvent(new Event('change',{bubbles:true}));_picking=false;}
  function open(){wrap.classList.add('open');render(inp.value);}
  inp.addEventListener('focus',open);
  inp.addEventListener('click',open);
  inp.addEventListener('input',()=>{if(_picking)return;wrap.classList.add('open');wrap.classList.toggle('has-val',!!inp.value);render(inp.value);});
  inp.addEventListener('keydown',e=>{
    const items=list.querySelectorAll('.combo-opt');
    if(e.key==='ArrowDown'){e.preventDefault();active=Math.min(active+1,items.length-1);}
    else if(e.key==='ArrowUp'){e.preventDefault();active=Math.max(active-1,0);}
    else if(e.key==='Enter'){if(active>=0){e.preventDefault();pick(items[active].dataset.v);}return;}
    else if(e.key==='Escape'){wrap.classList.remove('open');return;}
    items.forEach((it,i)=>it.classList.toggle('active',i===active));
    if(active>=0)items[active].scrollIntoView({block:'nearest'});
  });
  inp.addEventListener('blur',()=>setTimeout(()=>wrap.classList.remove('open'),150));
  clearBtn.addEventListener('mousedown',e=>{e.preventDefault();pick('');});
  wrap.classList.toggle('has-val',!!inp.value);
}

function dlOptions(datalistId){return ()=>{const dl=document.getElementById(datalistId);return dl?Array.from(dl.options).map(o=>o.value).filter(Boolean):[];};}

function syncComboVal(inputId){const inp=document.getElementById(inputId);const wrap=inp&&inp.closest('.combo');if(wrap)wrap.classList.toggle('has-val',!!inp.value);}

function buildInspectorCombo(){const el=$('#inspCombo');if(!el)return;el.innerHTML=`<div class="combo-ctl"><input id="inpInspector" class="combo-input" placeholder="Type inspector name" autocomplete="off"><span class="combo-clear">&times;</span><span class="combo-caret">▾</span></div><div class="combo-list"></div>`;const input=el.querySelector('.combo-input'),list=el.querySelector('.combo-list'),clear=el.querySelector('.combo-clear');let active=-1;const people=()=>{const role=AUTH.user?.role||'';if(role==='leader'||role==='inspector')return[cleanName(AUTH.user?.name||AUTH.user?.username||'')];let pool=entries;if(sel['project'])pool=pool.filter(e=>e.project===sel['project']);return uniq([...INSP_SEED,...pool.map(e=>e.inspector)]).filter(Boolean).sort((a,b)=>a.localeCompare(b,'th'));};function render(filter){let opts=people();const f=(filter||'').trim().toLowerCase();if(f)opts=opts.filter(o=>o.toLowerCase().includes(f));active=-1;let html=opts.map(o=>`<div class="combo-opt" data-v="${escAttr(o)}">${esc(o)}</div>`).join('');if(f&&!people().some(o=>o.toLowerCase()===f))html+=`<div class="combo-new" data-new="${escAttr(filter.trim())}">+ Use "${esc(filter.trim())}" (new)</div>`;if(!html)html=`<div class="combo-empty">Type inspector name</div>`;list.innerHTML=html;list.querySelectorAll('.combo-opt').forEach(o=>o.addEventListener('mousedown',e=>{e.preventDefault();pick(o.dataset.v);}));const nw=list.querySelector('.combo-new');if(nw)nw.addEventListener('mousedown',e=>{e.preventDefault();pick(nw.dataset.new);});}function pick(v){input.value=v;el.classList.toggle('has-val',!!v);el.classList.remove('open');}function open(){el.classList.add('open');render(input.value);}input.addEventListener('focus',open);input.addEventListener('click',open);input.addEventListener('input',()=>{el.classList.add('open');el.classList.toggle('has-val',!!input.value);render(input.value);});input.addEventListener('keydown',e=>{const items=list.querySelectorAll('.combo-opt,.combo-new');if(e.key==='ArrowDown'){e.preventDefault();active=Math.min(active+1,items.length-1);}else if(e.key==='ArrowUp'){e.preventDefault();active=Math.max(active-1,0);}else if(e.key==='Enter'){e.preventDefault();if(active>=0){const it=items[active];pick(it.dataset.v||it.dataset.new);}else if(input.value.trim())pick(input.value.trim());return;}else if(e.key==='Escape'){el.classList.remove('open');return;}items.forEach((it,i)=>it.classList.toggle('active',i===active));if(active>=0)items[active].scrollIntoView({block:'nearest'});});input.addEventListener('blur',()=>setTimeout(()=>el.classList.remove('open'),150));clear.addEventListener('mousedown',e=>{e.preventDefault();pick('');});}

let imgBusy=0;
// ย่อ/บีบอัดรูปในเครื่องก่อนอัปโหลด: ด้านยาวสุด 1280px, JPEG ลดคุณภาพจนไม่เกิน ~300KB (ภาพจากมือถือ 5–12MB → หลักร้อย KB)
async function compressImage(file,max=1280,limit=410000){
  const url=URL.createObjectURL(file);
  try{
    const img=await new Promise((res,rej)=>{const im=new Image();im.onload=()=>res(im);im.onerror=()=>rej(new Error('decode'));im.src=url;});
    let w=img.naturalWidth,h=img.naturalHeight;
    if(!w||!h)throw new Error('empty');
    if(w>h&&w>max){h=Math.round(h*max/w);w=max;}else if(h>=w&&h>max){w=Math.round(w*max/h);h=max;}
    const c=document.createElement('canvas');c.width=w;c.height=h;
    const g=c.getContext('2d');g.fillStyle='#fff';g.fillRect(0,0,w,h);g.drawImage(img,0,0,w,h);
    let q=0.72,data=c.toDataURL('image/jpeg',q);
    while(data.length>limit&&q>0.4){q-=0.1;data=c.toDataURL('image/jpeg',q);}
    c.width=c.height=0;
    return data;
  }finally{URL.revokeObjectURL(url);}
}
function wireImg(inputId,dropId,setter){$('#'+inputId).addEventListener('change',async e=>{
  const f=e.target.files[0];if(!f)return;
  const lbl=$('#'+dropId);imgBusy++;lbl.classList.add('img-busy');
  try{
    const data=await compressImage(f);
    setter(data);try{showPhotoQuality(lbl,await photoQuality(data));}catch(e){}lbl.classList.add('has-img');lbl.style.backgroundImage=`url(${data})`;const ph=lbl.querySelector('.ph-content');if(ph)ph.style.display='none';
  }catch(err){
    e.target.value='';toast('Could not read this photo. Please try another image (JPG or PNG)',false);
  }finally{imgBusy--;lbl.classList.remove('img-busy');}
});}
