async function saveEditUser(){
  const pend=$('#euProject')?$('#euProject').value.trim():'';
  if(pend&&!euProjects.includes(pend)){euProjects.push(pend);$('#euProject').value='';renderChips('euProjectChips',euProjects);}
  if(['leader','inspector'].includes($('#euRole').value)&&editUserTarget!=='admin'&&!euProjects.length){toast('Please assign at least one project to this user (otherwise they will see nothing)',false);return;}
  const updates={
    name:$('#euName').value.trim(),
    email:$('#euEmail').value.trim(),
    role:$('#euRole').value,
    project:euProjects.join(','),
    active:$('#euActive').checked?'true':'false'
  };
  if(editUserTarget==='admin'){delete updates.role;delete updates.project;delete updates.active;}
  if($('#euPassword').value.trim()) updates.password=$('#euPassword').value.trim();
  const btn=$('#euSave'); btn.disabled=true; btn.textContent='Saving…';
  const r=await api('updateUser',{username:editUserTarget,updates});
  btn.disabled=false; btn.textContent='Save';
  if(r&&r.ok){
    $('#editUserDlg').style.display='none';
    toast('User updated',true);
    await loadUsers();
  } else toast((r&&r.message)||'Update failed',false);
}
