function renderAwChips(containerId,arr){
  const box=document.getElementById(containerId);if(!box)return;
  box.innerHTML=arr.map((v,i)=>`<span class="chip">${esc(v)}<span class="chip-x" data-i="${i}">×</span></span>`).join('');
  box.querySelectorAll('.chip-x').forEach(x=>{
    x.onclick=()=>{arr.splice(parseInt(x.dataset.i,10),1);renderAwChips(containerId,arr);};
  });
}
function initAwMultiCombo(inputId,chipsId,arr,getOptionsFn){
  upgradeToCombo(inputId,()=>getOptionsFn().filter(v=>!arr.includes(v)));
  const inp=document.getElementById(inputId);
  if(!inp||inp.dataset.multiComboInited)return;
  inp.dataset.multiComboInited='1';
  inp.addEventListener('change',()=>{
    const v=inp.value.trim();
    if(v&&!arr.includes(v)){arr.push(v);renderAwChips(chipsId,arr);}
    _awClearComboVal(inputId);
  });
}

function _awClearComboVal(id){
  const inp=document.getElementById(id);if(!inp)return;
  inp.value='';const wrap=inp.closest('.combo');if(wrap)wrap.classList.remove('has-val');
  inp.dispatchEvent(new Event('change',{bubbles:true}));
}
function showAssignModal(){
  const modal=$('#assignModal');if(!modal)return;
  modal.style.display='flex';
  const role=AUTH.user?.role||'';
  const userProjs=(AUTH.user?.project||'').split(',').map(p=>p.trim()).filter(Boolean);

  awSelProjs.length=0;awSelLocs.length=0;awSelSubs.length=0;awSelEquips.length=0;
  renderAwChips('awProjectChips',awSelProjs);
  renderAwChips('awLocChips',awSelLocs);
  renderAwChips('awSubChips',awSelSubs);
  renderAwChips('awEquipChips',awSelEquips);

  initAwMultiCombo('awProject','awProjectChips',awSelProjs,()=>{
    let projs=uniq(master.map(m=>m.project)).filter(Boolean).sort((a,b)=>a.localeCompare(b,'th'));
    if(role==='leader')projs=projs.filter(p=>userProjs.includes(p));
    return projs;
  });
  upgradeToCombo('awAssignee',()=>{
    const r=AUTH.user?.role||'';
    const ups=(AUTH.user?.project||'').split(',').map(p=>p.trim()).filter(Boolean);
    const targetRoles=r==='admin'||r==='manager'?['leader','inspector']:['inspector'];
    let users=usersCache.filter(u=>targetRoles.includes(u.role)&&u.active!=='false'&&u.active!==false);
    if(r==='leader'&&ups.length)users=users.filter(u=>(u.project||'').split(',').map(p=>p.trim()).some(p=>ups.includes(p)));
    if(awSelProjs.length)users=users.filter(u=>awSelProjs.every(p=>(u.project||'').split(',').map(x=>x.trim()).includes(p)));
    return users.map(u=>(u.name||u.username)+' ('+u.role+')');
  });
  initAwMultiCombo('awLoc','awLocChips',awSelLocs,()=>{
    return uniq(master.filter(m=>!awSelProjs.length||awSelProjs.includes(m.project)).map(m=>m.locName)).filter(Boolean).sort((a,b)=>a.localeCompare(b,'th'));
  });
  initAwMultiCombo('awSub','awSubChips',awSelSubs,()=>{
    return uniq(master.filter(m=>(!awSelProjs.length||awSelProjs.includes(m.project))&&(!awSelLocs.length||awSelLocs.includes(m.locName))).map(m=>m.subName)).filter(Boolean).sort((a,b)=>a.localeCompare(b,'th'));
  });
  initAwMultiCombo('awEquip','awEquipChips',awSelEquips,()=>{
    return uniq(master.filter(m=>(!awSelProjs.length||awSelProjs.includes(m.project))&&(!awSelLocs.length||awSelLocs.includes(m.locName))&&(!awSelSubs.length||awSelSubs.includes(m.subName))).map(m=>m.equipment)).filter(Boolean).sort((a,b)=>a.localeCompare(b,'th'));
  });

  _awClearComboVal('awAssignee');

  document.querySelector('input[name="awScope"][value="project"]').checked=true;
  awScopeChange();
  $('#awNote').value='';
  const td=$('#awTargetDate');if(td)td.value='';
  const hint=$('#awTargetHint');if(hint)hint.innerHTML='';
}

