function _ptUpdateCurrentInfo(proj){
  const info=$('#ptCurrentInfo');if(!info)return;
  const dl=getProjectDeadline(proj);
  if(dl){
    const dInp=$('#ptDeadline');if(dInp)dInp.value=dl;
    const existing=targetsCache.find(t=>t.project===proj&&t.username==='__project__');
    if(existing&&existing.note&&$('#ptNote'))$('#ptNote').value=existing.note;
    info.style.display='';
    info.innerHTML=`<div style="font-size:11px;color:var(--ink-soft);margin-top:6px">Current deadline: <b>${dl}</b></div>`;
  } else {
    info.style.display='none';
  }
}
