async function saveAssignment(){
  if(!awSelProjs.length){toast('Please select at least one project',false);return;}
  const assignee=$('#awAssignee').value;
  if(!assignee){toast('Please select an assignee',false);return;}
  const validUser=usersCache.find(u=>u.username===assignee||((u.name||u.username)+' ('+u.role+')')===assignee);
  const resolvedAssignee=validUser?validUser.username:assignee;
  if(validUser&&['leader','inspector'].includes(validUser.role)){
    const userProjList=(validUser.project||'').split(',').map(p=>p.trim()).filter(Boolean);
    const invalid=awSelProjs.filter(p=>!userProjList.includes(p));
    if(invalid.length){toast('Assignee is not on the project: '+invalid.join(', ')+' — please fix this on the User Management page',false);return;}
  }
  const scope=document.querySelector('input[name="awScope"]:checked')?.value||'project';
  const note=$('#awNote').value.trim();
  const targetDate=$('#awTargetDate')?.value||'';
  for(const proj of awSelProjs){const projDL=getProjectDeadline(proj);if(targetDate&&projDL&&targetDate>projDL){toast('Due date must not be later than the project deadline '+proj+' ('+projDL+')',false);return;}}
  const by=AUTH.user?.username||'';
  let newItems=[];
  if(scope==='missing'){
    const chks=[...document.querySelectorAll('.aw-missing-chk:checked')];
    if(!chks.length){toast('Please select the items you want to fill in',false);return;}
    chks.forEach(c=>{
      const m=master.find(x=>x.id===c.dataset.id);if(!m)return;
      const mf=[!m.brand&&'brand',!m.model&&'model',!m.serial&&'serial'].filter(Boolean);
      newItems.push({id:uid(),project:m.project,scopeType:'missing',locName:m.locName,subName:m.subName,equipment:m.equipment,masterId:m.id,missingFields:mf,assignedTo:resolvedAssignee,assignedBy:by,note,status:'pending',createdAt:Date.now(),doneAt:null,doneData:{},targetDate});
    });
  } else if(scope==='project'){
    awSelProjs.forEach(proj=>newItems.push({id:uid(),project:proj,scopeType:'project',locName:'',subName:'',equipment:'',masterId:'',missingFields:[],assignedTo:resolvedAssignee,assignedBy:by,note,status:'pending',createdAt:Date.now(),doneAt:null,doneData:{},targetDate}));
  } else if(scope==='loc'){
    if(!awSelLocs.length){toast('Please select at least one location',false);return;}
    awSelProjs.forEach(proj=>awSelLocs.forEach(loc=>newItems.push({id:uid(),project:proj,scopeType:'loc',locName:loc,subName:'',equipment:'',masterId:'',missingFields:[],assignedTo:resolvedAssignee,assignedBy:by,note,status:'pending',createdAt:Date.now(),doneAt:null,doneData:{},targetDate})));
  } else if(scope==='sub'){
    if(!awSelSubs.length){toast('Please select at least one sub-location',false);return;}
    const locs=awSelLocs.length?awSelLocs:[''];
    awSelProjs.forEach(proj=>locs.forEach(loc=>awSelSubs.forEach(sub=>newItems.push({id:uid(),project:proj,scopeType:'sub',locName:loc,subName:sub,equipment:'',masterId:'',missingFields:[],assignedTo:resolvedAssignee,assignedBy:by,note,status:'pending',createdAt:Date.now(),doneAt:null,doneData:{},targetDate}))));
  } else if(scope==='equip'){
    if(!awSelEquips.length){toast('Please select at least one equipment',false);return;}
    const locs=awSelLocs.length?awSelLocs:[''];const subs=awSelSubs.length?awSelSubs:[''];
    awSelProjs.forEach(proj=>locs.forEach(loc=>subs.forEach(sub=>awSelEquips.forEach(eq=>newItems.push({id:uid(),project:proj,scopeType:'equip',locName:loc,subName:sub,equipment:eq,masterId:'',missingFields:[],assignedTo:resolvedAssignee,assignedBy:by,note,status:'pending',createdAt:Date.now(),doneAt:null,doneData:{},targetDate})))));
  }
  if(!newItems.length){toast('No records to save',false);return;}
  assignments.push(...newItems);
  await sSet(ASSIGN_KEY,JSON.stringify(assignments));
  if(AUTH.token){for(const a of newItems)await api(ACT.saveAssignment,{assignment:a});}
  $('#assignModal').style.display='none';
  renderMyAssignments();
  await loadAssignStats();
  toast('Assigned Work '+newItems.length+' records',true);
}

let _fillingAssignId=null;
function openFillData(assignId){
  const a=assignments.find(x=>x.id===assignId);if(!a)return;
  const m=master.find(x=>x.id===a.masterId);
  _fillingAssignId=assignId;
  const info=$('#fillDataInfo');
  const fields=$('#fillDataFields');
  if(info)info.innerHTML=`<b>${esc(a.equipment)}</b><br><span style="color:var(--ink-faint)">${esc(a.subName)} · ${esc(a.locName)} · ${esc(a.project)}</span>`;
  if(fields){
    fields.innerHTML=(a.missingFields||[]).map(f=>{
      const label={brand:'Brand',model:'Model',serial:'Serial Number'}[f]||f;
      const cur=m?m[f]||'':'';
      return `<div><label style="font-size:12px;font-weight:600;color:var(--ink-soft);display:block;margin-bottom:4px">${esc(label)}</label><input type="text" class="tin" data-field="${f}" value="${esc(cur)}" placeholder="${esc(label)}…" style="width:100%"></div>`;
    }).join('');
  }
  const modal=$('#fillDataModal');if(modal)modal.style.display='flex';
}

async function saveFillData(){
  if(!_fillingAssignId)return;
  const a=assignments.find(x=>x.id===_fillingAssignId);if(!a)return;
  const doneData={};
  $('#fillDataFields').querySelectorAll('input[data-field]').forEach(inp=>{doneData[inp.dataset.field]=inp.value.trim();});
  a.status='done';a.doneAt=Date.now();a.doneData=doneData;

  const m=master.find(x=>x.id===a.masterId);
  if(m){Object.assign(m,doneData);await persistMaster();if(AUTH.user&&AUTH.user.role==='admin')await masterServer('masterUpsert',{rows:[masterToBackend(m)]});}
  await sSet(ASSIGN_KEY,JSON.stringify(assignments));
  if(AUTH.token)await api(ACT.completeAssignment,{id:a.id,doneData});
  $('#fillDataModal').style.display='none';
  renderMyAssignments();
  toast('Data saved',true);
}

async function exportAssignData(){
  const done=assignments.filter(a=>a.scopeType==='missing'&&a.status==='done');
  if(!done.length){toast('No completed work yet',false);return;}
  const header=['Order','Project','System','Location Type','Location','Sub-location','Equipment Type','Equipment','Brand','Model','Serial Number'];
  const rows=done.map(a=>{
    const m=master.find(x=>x.id===a.masterId)||{};
    return [m.order||'',a.project,m.system||'',m.typeLocation||'',a.locName,a.subName,m.asset||'',a.equipment,a.doneData.brand||m.brand||'',a.doneData.model||m.model||'',a.doneData.serial||m.serial||''];
  });
  try{await loadLib('xlsx');}catch(e){toast('Could not load the Excel library. Check your connection and try again',false); return;}
  const ws=XLSX.utils.aoa_to_sheet([header,...rows]);
  const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'AssignData');
  XLSX.writeFile(wb,'assign_data_'+fileStamp(Date.now())+'.xlsx');
  toast('Download '+done.length+' records',true);
}

